"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 shortcut check (plan 8.3; step 0 item 10). Run before any training; every gate AUC must be <= 0.55.

A gradient-boosted classifier (as in v0.3) sees only generator metadata, never audio or text, is trained on the train
renders and scored on dev (AUC: 0.5 = chance). Gate features per contrast follow plan 8.3; a parameter that a version
does not have (for example the footstep level in a version without footsteps) is filled with random draws from that
parameter's training values, so the classifier sees parameter values, not which sounds are present (presence is the
scene's content). Diagnostic
features (plan 8.3: word count, position in the episode, time since the event; for S-react also whether the ring
still rings at the decision point, user decision 2026-11-14; for episode R also the pause before the line and whether
the user stands at the door, user decision 2026-11-15) are reported but never gate. The episode R gate is computed on
the lines not spoken at the door.
usage: python -I scripts/p1v4_shortcut_check.py [train meta dir] [dev meta dir]
"""
import json
import os
import sys
import zlib

import numpy as np
from sklearn.ensemble import HistGradientBoostingClassifier
from sklearn.metrics import roc_auc_score

POS = {"near": 0, "across": 1, "door": 2}


def load(d, excl="results/step0_v04/excluded_units.json"):
    """Unit rows of a render dir, without the units excluded under plan 8.4 (TV speakers in the speaker-ID model's
    training data or without a name)."""
    p = os.path.join(d, "meta.jsonl")
    ex = ({u for us in json.load(open(excl, encoding="utf-8"))["units"].values() for u in us}
          if os.path.exists(excl) else set())
    return [r for r in (json.loads(line) for line in open(p, encoding="utf-8")) if r["unit"] not in ex]         if os.path.exists(p) else []


def src(r, sid):
    return next((s for s in r["sources"] if s["id"] == sid), None)


def common(r):
    sp = r["spec"]
    return {"room": 0 if sp["room"].startswith("small") else 1, "noise": zlib.crc32(sp["noise"].encode()) % 97,
            "snr": sp["snr_db"],
            "lead": sp.get("lead_in", 0.0), "gain": r.get("gain_db", 0.0)}


def single_rows(rows, part):
    out = []
    for r in rows:
        if r["part"] != part or r["subset"] is not None:
            continue
        sp, p = r["spec"], r["points"][0]
        ev, line = src(r, "ev"), src(r, "line")
        f = common(r)
        f.update({"ev_db": sp.get("ev_db"), "user_pos": POS.get(sp.get("user_pos"), np.nan),
                  "ev_pos": POS.get(sp.get("ev_pos"), np.nan)})
        diag = {}
        if part == "r_hear":
            f.update({"dur": sp["dur"], "gap": sp["gap"], "onset_rel": sp["dur"] + sp["gap"],
                      "after_agent": int(sp["after_agent"]), "silence": sp["silence"],
                      "fmt": (zlib.crc32(os.path.splitext((ev or {}).get("path", "x.wav"))[1].encode()) % 11
                              if ev else np.nan),
                      "src": 0 if ev and "fsd50k" in ev.get("path", "") else (1 if ev else np.nan)})
            diag["abs_onset"] = p["t"] - ev["start"] if ev else np.nan
            y = 1 if r["version"] == "1" else (0 if r["version"] == "3" else None)
        elif part in ("r_react", "s_react"):
            f.update({"ring": sp["ring"], "cut": (ev["start"] + sp["ring"]) if ev else np.nan, "gap": sp["gap"]})
            if part == "r_react":
                f["silence"] = sp["silence"]
                y = 1 if r["version"] == "1" else 0
            else:       # structural, diagnostic only (author, 2026-11-14): an answered phone stops ringing
                diag["ring_on"] = int(ev is not None and ev["end"] > p["t"] - 1e-3)
                diag["dec_since_ev"] = p["t"] - ev["start"] if ev else np.nan
                y = 1 if r["version"] == "1" else 0
            diag["words"] = len(line["text"].split()) if line else 0
        elif part == "s_move":
            steps = [s for s in r["sources"] if s.get("cls") == "footsteps"]
            door = src(r, "door")
            tv = src(r, "tv")
            a0 = r["assistant"][0]["start"] if r["assistant"] else 0.0
            f.update({"t_dec": p["t"], "t_dec_since_assistant": p["t"] - a0,
                      "step_db": steps[0]["db"] if steps else np.nan,
                      "step_n": len(steps) if steps else np.nan,
                      "door_db": door["db"] if door else np.nan, "tv_db": tv["db"] if tv else np.nan})
            diag["visitor_speaks"] = int(bool(sp.get("visitor_speaks"))) if r["version"] == "1" else 0
            y = 1 if r["version"] == "1" else 0
        if y is None:
            continue
        out.append((f, diag, y))
    return out


def episode_rows(rows):
    resp, silent = [], []
    for r in rows:
        if r["part"] != "episode" or r["subset"] is not None:
            continue
        srcs = sorted(r["sources"], key=lambda s: s["start"])
        evs = [s for s in srcs if s.get("cls") in ("phone", "doorbell", "knock")]
        t_ev = evs[0]["start"] if evs else np.nan
        users = [s for s in srcs if s.get("who") == "user"]
        for k, p in enumerate(r["points"]):
            f = common(r)
            if p["line"]:
                s = next(x for x in srcs if x["id"] == p["line"])
                prev = [x["end"] for x in srcs if x["end"] <= s["start"] + 1e-6 and x["id"] != s["id"]]
                prev += [a["end"] for a in r["assistant"] if a["end"] <= s["start"] + 1e-6]
                f.update({"pos": POS.get(s["pos"], np.nan), "db": s["db"]})
                # structural, diagnostic only (author, 2026-11-15): a caller cannot be heard, so lines to a caller follow
                # listening pauses; at the door the user talks to the visitor
                diag = {"words": len(s["text"].split()), "index": users.index(s) if s in users else -1,
                        "since_event": p["t"] - t_ev if evs else np.nan,
                        "pause": s["start"] - max(prev) if prev else np.nan, "at_door": int(s["pos"] == "door")}
                if p["gold"].get("R") is not None:
                    resp.append((f, diag, 1 if p["gold"]["R"] == "not" else 0))
            elif p["kind"] == "S":
                f.update({"since_event": p["t"] - t_ev if evs else np.nan,
                          "ev_db": evs[0]["db"] if evs else np.nan, "ev_pos": POS.get(evs[0]["pos"], np.nan) if evs
                          else np.nan})
                silent.append((f, {"door_sound": int(bool(evs) and evs[0]["cls"] in ("doorbell", "knock"))},
                               1 if p["gold"]["S"] == "stop" else 0))
    return resp, silent


def auc(tr, dv, which="gate", drop=(), only=None):
    """Gate AUC on dev of a classifier trained on train. A parameter a version does not have is filled with a random
    draw from that parameter's training values (seeded), so its absence carries no information: which sounds a version
    contains is the scene's content, not a generator parameter. (A constant fill such as the median would show up as a
    spike the trees can find, which is what made S-move fail at 0.83 on 2026-11-14.)"""
    if len({y for _, _, y in tr}) < 2 or len({y for _, _, y in dv}) < 2:
        return None
    pick = {"gate": lambda f, d: f, "diag": lambda f, d: d, "both": lambda f, d: {**f, **d}}[which]
    keys = [k for k in sorted(pick(tr[0][0], tr[0][1])) if k not in drop and (only is None or k in only)]
    if not keys:
        return None
    X = np.array([[pick(f, d).get(k, np.nan) for k in keys] for f, d, _ in tr], float)
    Xd = np.array([[pick(f, d).get(k, np.nan) for k in keys] for f, d, _ in dv], float)
    rng = np.random.default_rng(20261114)
    for j in range(len(keys)):
        pool = X[~np.isnan(X[:, j]), j]
        pool = pool if len(pool) else np.zeros(1)
        for M in (X, Xd):
            miss = np.isnan(M[:, j])
            M[miss, j] = rng.choice(pool, miss.sum())
    y, yd = np.array([y for *_, y in tr]), np.array([y for *_, y in dv])
    clf = HistGradientBoostingClassifier(max_iter=200, random_state=0).fit(X, y)
    return round(float(roc_auc_score(yd, clf.predict_proba(Xd)[:, 1])), 4), len(tr), len(dv), keys


def main(train_dir="data/p1v4/render/train_d00", dev_dir="data/p1v4/render/dev"):
    tr, dv = load(train_dir), load(dev_dir)
    res = {}
    for part in ("r_hear", "r_react", "s_react", "s_move"):
        a, b = single_rows(tr, part), single_rows(dv, part)
        if a and b:
            g, d = auc(a, b, "gate"), auc(a, b, "diag")
            res[part] = {"gate_auc": g[0] if g else None, "n_train": g[1] if g else 0, "n_dev": g[2] if g else 0,
                         "gate_features": g[3] if g else [], "diag_auc": d[0] if d else None}
            if part == "s_react":                   # the structural features alone (diagnostic, user 2026-11-14)
                res[part]["diag_auc_ring_on_alone"] = (auc(a, b, "diag", only=("ring_on",)) or [None])[0]
                res[part]["diag_auc_time_since_event_alone"] = (auc(a, b, "diag", only=("dec_since_ev",)) or [None])[0]
    er_tr, es_tr = episode_rows(tr)
    er_dv, es_dv = episode_rows(dv)
    # Silent S points: a silent walk to the door can only follow a door sound, so stop and continue are compared after
    # door sounds (which sound happened is the scene's content); all sounds together are shown as a diagnostic.
    door = [x for x in es_tr if x[1]["door_sound"]], [x for x in es_dv if x[1]["door_sound"]]
    # Episode R (author, 2026-11-15): the gate compares lines to the assistant and to others away from the door; the
    # pause before the line and the door position are reported as diagnostics.
    nd = [x for x in er_tr if not x[1]["at_door"]], [x for x in er_dv if not x[1]["at_door"]]
    for name, a, b in (("episode_R", nd[0], nd[1]), ("episode_silent_S", door[0], door[1])):
        if a and b:
            g, d = auc(a, b, "gate"), auc(a, b, "diag")
            res[name] = {"gate_auc": g[0] if g else None, "n_train": g[1] if g else 0, "n_dev": g[2] if g else 0,
                         "gate_features": g[3] if g else [], "diag_auc": d[0] if d else None}
    if "episode_R" in res:
        gk = tuple(res["episode_R"]["gate_features"])
        res["episode_R"].update({
            "diag_auc_pause_alone": (auc(nd[0], nd[1], "diag", only=("pause",)) or [None])[0],
            "diag_auc_pause_alone_all_lines": (auc(er_tr, er_dv, "diag", only=("pause",)) or [None])[0],
            "diag_auc_at_door_alone_all_lines": (auc(er_tr, er_dv, "diag", only=("at_door",)) or [None])[0],
            "gate_auc_all_lines_with_pause_diagnostic": (auc(er_tr, er_dv, "both", only=gk + ("pause",)) or
                                                         [None])[0],
            "n_train_all_lines": len(er_tr), "n_dev_all_lines": len(er_dv)})
    if es_tr and es_dv and "episode_silent_S" in res:
        res["episode_silent_S"]["gate_auc_all_sounds_diagnostic"] = (auc(es_tr, es_dv, "gate") or [None])[0]
    res["pass"] = all(v["gate_auc"] is not None and v["gate_auc"] <= 0.55 for k, v in res.items() if k != "pass")
    os.makedirs("results/step0_v04", exist_ok=True)
    json.dump(res, open("results/step0_v04/shortcut_check.json", "w"), indent=1)
    for k, v in res.items():
        print(k, v if k == "pass" else {x: v[x] for x in v if x != "gate_features"})


if __name__ == "__main__":
    main(*sys.argv[1:3])
